test('invoiceTotals with voucher exceeding total', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 2 }],
  });
  assert.equal(invoice.ok, true);
  const totals1 = invoiceTotals(invoice.value);
  const vouchered = applyVoucher(invoice.value, { code: 'SAVE_EXCESS', amount: totals1.value.total + 1000 });
  const totals2 = invoiceTotals(vouchered.value);
  assert.equal(totals2.value.total, 0);
});

test('invoiceTotals bulk discount: 10+ units get 2.5% off', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 1000, vatRate: 21 }],
  };
  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  assert.equal(r.value.subtotal, 10000);
  const bulkDiscount = 10000 * 0.025;
  assert.equal(r.value.discount, bulkDiscount);
  const discountedAmount = 10000 - bulkDiscount;
  const expectedVat = Math.round(discountedAmount * 0.21);
  const expectedTotal = 10000 - bulkDiscount + expectedVat;
  assert.equal(r.value.vat, expectedVat);
  assert.equal(r.value.total, expectedTotal);
});

test('invoiceTotals bulk discount not applied for 9 units', () => {
  const invoice = {
    lines: [{ qty: 9, unitPrice: 1000, vatRate: 21 }],
  };
  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  assert.equal(r.value.subtotal, 9000);
  assert.equal(r.value.discount, 0);
  const expectedVat = Math.round(9000 * 0.21);
  const expectedTotal = 9000 + expectedVat;
  assert.equal(r.value.vat, expectedVat);
  assert.equal(r.value.total, expectedTotal);
});

test('invoiceTotals bulk discount applied after line discount', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 1000, discountPercent: 10, vatRate: 21 }],
  };
  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  assert.equal(r.value.subtotal, 10000);
  const lineDiscount = 10000 * 0.1;
  const afterLineDiscount = 10000 - lineDiscount;
  const bulkDiscount = afterLineDiscount * 0.025;
  const totalDiscount = lineDiscount + bulkDiscount;
  assert.equal(r.value.discount, totalDiscount);
  const discountedAmount = 10000 - totalDiscount;
  const expectedVat = Math.round(discountedAmount * 0.21);
  const expectedTotal = 10000 - totalDiscount + expectedVat;
  assert.equal(r.value.vat, expectedVat);
  assert.equal(r.value.total, expectedTotal);
});

test('invoiceTotals bulk discount with tier discount', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(invoice.ok, true);
  const r = invoiceTotals(invoice.value);
  assert.equal(r.ok, true);
  assert.equal(r.value.subtotal, 85000);
  const tierDiscount = 85000 * 0.05;
  const afterTierDiscount = 85000 - tierDiscount;
  const bulkDiscount = afterTierDiscount * 0.025;
  const totalDiscount = tierDiscount + bulkDiscount;
  assert.equal(r.value.discount, totalDiscount);
});

test('invoiceTotals multiple lines, some with bulk discount', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, vatRate: 21 },
      { qty: 5, unitPrice: 1000, vatRate: 21 },
    ],
  };
  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  assert.equal(r.value.subtotal, 15000);
  const line1BulkDiscount = 10000 * 0.025;
  const totalDiscount = line1BulkDiscount;
  assert.equal(r.value.discount, totalDiscount);
  const line1Discounted = 10000 - line1BulkDiscount;
  const line2Discounted = 5000;
  const expectedVat = Math.round(line1Discounted * 0.21) + Math.round(line2Discounted * 0.21);
  const expectedTotal = 15000 - totalDiscount + expectedVat;
  assert.equal(r.value.vat, expectedVat);
  assert.equal(r.value.total, expectedTotal);
});

test('invoiceTotals bulk discount with both line and bulk discount', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, discountPercent: 5, vatRate: 21 },
      { qty: 10, unitPrice: 1000, discountPercent: 10, vatRate: 21 },
    ],
  };
  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  assert.equal(r.value.subtotal, 20000);
  const line1LineDiscount = 10000 * 0.05;
  const line1AfterLineDiscount = 10000 - line1LineDiscount;
  const line1BulkDiscount = line1AfterLineDiscount * 0.025;
  const line2LineDiscount = 10000 * 0.1;
  const line2AfterLineDiscount = 10000 - line2LineDiscount;
  const line2BulkDiscount = line2AfterLineDiscount * 0.025;
  const totalDiscount = line1LineDiscount + line1BulkDiscount + line2LineDiscount + line2BulkDiscount;
  assert.equal(r.value.discount, totalDiscount);
});

test('invoiceTotals bulk discount threshold at exactly 10', () => {
  const r1 = invoiceTotals({ lines: [{ qty: 10, unitPrice: 1000, vatRate: 0 }] });
  const r9 = invoiceTotals({ lines: [{ qty: 9, unitPrice: 1000, vatRate: 0 }] });
  assert.equal(r1.ok, true);
  assert.equal(r9.ok, true);
  assert.equal(r1.value.discount, 10000 * 0.025);
  assert.equal(r9.value.discount, 0);
});

test('invoiceTotals bulk discount with large quantities', () => {
  const invoice = {
    lines: [{ qty: 100, unitPrice: 1000, vatRate: 21 }],
  };
  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  assert.equal(r.value.subtotal, 100000);
  const bulkDiscount = 100000 * 0.025;
  assert.equal(r.value.discount, bulkDiscount);
  const discountedAmount = 100000 - bulkDiscount;
  const expectedVat = Math.round(discountedAmount * 0.21);
  const expectedTotal = 100000 - bulkDiscount + expectedVat;
  assert.equal(r.value.vat, expectedVat);
  assert.equal(r.value.total, expectedTotal);
});

test('invoiceTotals bulk discount stacks with tier discount', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(invoice.ok, true);
  const r = invoiceTotals(invoice.value);
  assert.equal(r.ok, true);
  const silverDiscount = 85000 * 0.025;
  const afterTierDiscount = 85000 - silverDiscount;
  const bulkDiscount = afterTierDiscount * 0.025;
  const totalDiscount = silverDiscount + bulkDiscount;
  assert.equal(r.value.discount, totalDiscount);
  assert.ok(totalDiscount > silverDiscount);
});

test('invoiceTotals bulk discount applies even with 100% line discount', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 1000, discountPercent: 100, vatRate: 21 }],
  };
  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  assert.equal(r.value.subtotal, 10000);
  assert.equal(r.value.discount, 10000);
  assert.equal(r.value.vat, 0);
  assert.equal(r.value.total, 0);
});

test('invoiceTotals bulk discount with mixed line quantities', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
