import test from 'node:test';
import assert from 'node:assert/strict';
import { lineTotal, invoiceTotals } from '../src/totals.js';
import { createInvoice, issueInvoice, addLine, removeLine, applyVoucher } from '../src/invoices.js';

test('lineTotal calculates qty × unitPrice', () => {
  const r = lineTotal({ qty: 5, unitPrice: 8500 });
  assert.equal(r.ok, true);
  assert.equal(r.value, 42500);
});

test('lineTotal handles various quantities and prices', () => {
  assert.equal(lineTotal({ qty: 1, unitPrice: 100 }).value, 100);
  assert.equal(lineTotal({ qty: 10, unitPrice: 1000 }).value, 10000);
  assert.equal(lineTotal({ qty: 3, unitPrice: 120000 }).value, 360000);
});

test('lineTotal validates qty is a positive integer', () => {
  const cases = [
    { qty: 0, error: 'QTY_INVALID' },
    { qty: -5, error: 'QTY_INVALID' },
    { qty: 1.5, error: 'QTY_INVALID' },
    { qty: '5', error: 'QTY_INVALID' },
    { qty: null, error: 'QTY_INVALID' },
  ];
  for (const c of cases) {
    const r = lineTotal({ qty: c.qty, unitPrice: 100 });
    assert.deepEqual(r, { ok: false, error: c.error }, `should reject qty=${c.qty}`);
  }
});

test('lineTotal validates unitPrice is a non-negative integer', () => {
  const cases = [
    { unitPrice: -100, error: 'AMOUNT_INVALID' },
    { unitPrice: 1.5, error: 'AMOUNT_INVALID' },
    { unitPrice: '100', error: 'AMOUNT_INVALID' },
    { unitPrice: null, error: 'AMOUNT_INVALID' },
  ];
  for (const c of cases) {
    const r = lineTotal({ qty: 1, unitPrice: c.unitPrice });
    assert.deepEqual(r, { ok: false, error: c.error }, `should reject unitPrice=${c.unitPrice}`);
  }
});

test('lineTotal accepts zero unitPrice', () => {
  const r = lineTotal({ qty: 5, unitPrice: 0 });
  assert.equal(r.ok, true);
  assert.equal(r.value, 0);
});

test('invoiceTotals calculates subtotal, discount, vat and total', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 8500, vatRate: 21 },
      { qty: 1, unitPrice: 120000, vatRate: 21 },
    ],
  };
  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  assert.equal(r.value.subtotal, 162500);
  assert.equal(r.value.discount, 0);
  assert.equal(r.value.vat, 34125);
  assert.equal(r.value.total, 196625);
});

test('invoiceTotals sums multiple line totals', () => {
  const invoice = {
    lines: [
      { qty: 3, unitPrice: 100, vatRate: 21 },
      { qty: 2, unitPrice: 200, vatRate: 21 },
      { qty: 1, unitPrice: 500, vatRate: 21 },
    ],
  };
  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  assert.equal(r.value.subtotal, 1200);
  assert.equal(r.value.discount, 0);
  assert.equal(r.value.vat, 252);
  assert.equal(r.value.total, 1452);
});

test('invoiceTotals returns an object with subtotal, discount, vat and total', () => {
  const invoice = {
    lines: [{ qty: 1, unitPrice: 100, vatRate: 21 }],
  };
  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  assert.ok('subtotal' in r.value);
  assert.ok('discount' in r.value);
  assert.ok('vat' in r.value);
  assert.ok('total' in r.value);
});

test('invoiceTotals validates invoice has lines', () => {
  const cases = [null, {}, { lines: null }, { lines: [] }];
  for (const invoice of cases) {
    const r = invoiceTotals(invoice);
    assert.deepEqual(r, { ok: false, error: 'NO_LINES' });
  }
});

test('invoiceTotals propagates line validation errors', () => {
  const invoice = {
    lines: [
      { qty: 1, unitPrice: 100 },
      { qty: 0, unitPrice: 100 },
    ],
  };
  const r = invoiceTotals(invoice);
  assert.deepEqual(r, { ok: false, error: 'QTY_INVALID' });
});

test('invoiceTotals works with real invoices from createInvoice', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });
  assert.equal(invoice.ok, true);
  const r = invoiceTotals(invoice.value);
  assert.equal(r.ok, true);
  assert.equal(r.value.subtotal, 5 * 8500 + 1 * 120000);
  assert.equal(r.value.discount, 0);
  assert.equal(r.value.vat, 34125);
  assert.equal(r.value.total, 196625);
});

test('invoiceTotals calculates discount on a single line', () => {
  const invoice = {
    lines: [{ qty: 5, unitPrice: 1000, discountPercent: 10 }],
  };
  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  assert.equal(r.value.subtotal, 5000);
  assert.equal(r.value.discount, 500);
  assert.equal(r.value.total, 4500);
});

