import test from 'node:test';
import assert from 'node:assert/strict';
import { lineTotal, invoiceTotals } from '../src/totals.js';
import { createInvoice, issueInvoice, addLine, removeLine, applyVoucher } from '../src/invoices.js';

test('lineTotal calculates qty × unitPrice', () => {
  const r = lineTotal({ qty: 5, unitPrice: 8500 });
  assert.equal(r.ok, true);
  assert.equal(r.value, 42500);
});

test('lineTotal handles various quantities and prices', () => {
  assert.equal(lineTotal({ qty: 1, unitPrice: 100 }).value, 100);
  assert.equal(lineTotal({ qty: 10, unitPrice: 1000 }).value, 10000);
  assert.equal(lineTotal({ qty: 3, unitPrice: 120000 }).value, 360000);
});

test('lineTotal validates qty is a positive integer', () => {
  const cases = [
    { qty: 0, error: 'QTY_INVALID' },
    { qty: -5, error: 'QTY_INVALID' },
    { qty: 1.5, error: 'QTY_INVALID' },
    { qty: '5', error: 'QTY_INVALID' },
    { qty: null, error: 'QTY_INVALID' },
  ];
  for (const c of cases) {
    const r = lineTotal({ qty: c.qty, unitPrice: 100 });
    assert.deepEqual(r, { ok: false, error: c.error }, `should reject qty=${c.qty}`);
  }
});

test('lineTotal validates unitPrice is a non-negative integer', () => {
  const cases = [
    { unitPrice: -100, error: 'AMOUNT_INVALID' },
    { unitPrice: 1.5, error: 'AMOUNT_INVALID' },
    { unitPrice: '100', error: 'AMOUNT_INVALID' },
    { unitPrice: null, error: 'AMOUNT_INVALID' },
  ];
  for (const c of cases) {
    const r = lineTotal({ qty: 1, unitPrice: c.unitPrice });
    assert.deepEqual(r, { ok: false, error: c.error }, `should reject unitPrice=${c.unitPrice}`);
  }
});

test('lineTotal accepts zero unitPrice', () => {
  const r = lineTotal({ qty: 5, unitPrice: 0 });
  assert.equal(r.ok, true);
  assert.equal(r.value, 0);
});

