  assert.equal(r.value.discount, 500);
  const discountedAmount = 4500;
  const expectedVat = Math.round(discountedAmount * 0.21);
  const expectedTotal = 5000 - 500 + expectedVat;
  assert.equal(r.value.vat, expectedVat);
  assert.equal(r.value.total, expectedTotal);
});

test('invoiceTotals handles multiple VAT rates', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 1000, vatRate: 21 },
