  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  assert.equal(r.value.subtotal, 8000);
  assert.equal(r.value.discount, 0);
  const vat21 = Math.round(5000 * 0.21);
  const vat9 = Math.round(2000 * 0.09);
  const vat0 = Math.round(1000 * 0.00);
  const expectedVat = vat21 + vat9 + vat0;
  const expectedTotal = 8000 + expectedVat;
  assert.equal(r.value.vat, expectedVat);
  assert.equal(r.value.total, expectedTotal);
});

