    ],
  });
  const issued = issueInvoice(invoice.value, []);
  const totals = invoiceTotals(issued.value);
  const r = vatSummary([issued.value]);
  assert.equal(r.length, 2);
  assert.equal(r[0].rate, 21);
  assert.equal(r[1].rate, 9);
  // Verify that vat rate calculations are correct
  assert.ok(r[0].base > 0);
  assert.ok(r[1].base > 0);
});

test('vatSummary with large dataset', () => {
  const invoices = Array.from({ length: 10 }, (_, i) => {
    const invoice = createInvoice({
      customerId: 'C-001',
      issueDate: `2026-10-${String((i % 20) + 1).padStart(2, '0')}`,
      lines: [{ sku: 'DES-HOUR', qty: i + 1 }],
    });
    return issueInvoice(invoice.value, []);
  })
    .filter((inv) => inv.ok)
    .map((inv) => inv.value);
  const r = vatSummary(invoices);
  assert.equal(r.length, 1);
  assert.equal(r[0].rate, 21);
  assert.ok(r[0].base > 0);
  assert.ok(r[0].vat > 0);
});

