  // dueDate = 2026-10-21, asOf = 2026-10-22, daysOverdue = 1
  // due = 100 + 21 = 121 cents
  // fee = 121 × 0.0004 × 1 = 0.0484 → roundCents = 0 (round to nearest cent, half to even)
  // Actually, let me recalculate: 0.0484 rounds to 0
  assert.equal(r, 0);
});

test('lateFee calculates fee for 7 days overdue', () => {
