  assert.equal(r[0].due, totals.value.total - 30);
});

test('overdueInvoices sorts by daysOverdue descending', () => {
  const invoice1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'STICKER', qty: 1 }],
    terms: 'NET14',
  });
  const issued1 = issueInvoice(invoice1.value, []);

  const invoice2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-10',
    lines: [{ sku: 'STICKER', qty: 1 }],
    terms: 'NET14',
  });
  const issued2 = issueInvoice(invoice2.value, ['INV-2026-0001']);

  const invoice3 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-05',
    lines: [{ sku: 'STICKER', qty: 1 }],
    terms: 'NET14',
  });
  const issued3 = issueInvoice(invoice3.value, ['INV-2026-0001', 'INV-2026-0002']);

  const r = overdueInvoices([issued1.value, issued2.value, issued3.value], '2026-10-31');
  assert.equal(r.length, 3);
  assert.equal(r[0].daysOverdue, 16); // Oct 1 + 14 = Oct 15, overdue by 16 days on Oct 31
  assert.equal(r[1].daysOverdue, 12); // Oct 5 + 14 = Oct 19, overdue by 12 days on Oct 31
  assert.equal(r[2].daysOverdue, 7); // Oct 10 + 14 = Oct 24, overdue by 7 days on Oct 31
});

test('overdueInvoices with multiple invoices from same customer', () => {
  const invoice1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'STICKER', qty: 1 }],
