test('vatSummary calculates base and vat correctly', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 10 }],
  });
  const issued = issueInvoice(invoice.value, []);
  const r = vatSummary([issued.value]);
  assert.equal(r.length, 1);
  // STICKER: 10 × 50 = 500 cents, no discount
  // base = 500, vat = 500 × 0.21 = 105
