test('vatSummary with discount', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10, discountPercent: 10 }],
  });
  const issued = issueInvoice(invoice.value, []);
  const r = vatSummary([issued.value]);
  assert.equal(r.length, 1);
  // DES-HOUR: 10 × 8500 = 85000
  // discount: 85000 × 0.10 = 8500
  // base: 85000 - 8500 = 76500
  // vat: 76500 × 0.21 = 16065
  assert.equal(r[0].rate, 21);
  assert.equal(r[0].base, 76500);
  assert.equal(r[0].vat, 16065);
});

test('vatSummary with tier discount', () => {
