  const r = vatSummary([issued.value]);
  assert.equal(r.length, 1);
  // DES-HOUR: 10 × 8500 = 85000
  // discount: 85000 × 0.05 = 4250 (gold tier)
  // base: 85000 - 4250 = 80750
  // vat: 80750 × 0.21 = 16957.5 → roundCents = 16958
  assert.equal(r[0].rate, 21);
  assert.equal(r[0].base, 80750);
  assert.equal(r[0].vat, 16958);
});

